// A BASE das instâncias web. Ela existe por UM motivo: a busca da pintura na
// tabela medida é idêntica em toda peça, e repeti-la em cada elemento seria
// convidar a divergência que esta arquitetura existe pra impedir.
//
// Ela NÃO é uma camada de componente. Não desenha, não decide geometria e não
// conhece nenhuma peça — recebe um slug e uma combinação, e devolve papel.
import { pintura } from './pintura.g.js';

/// O PAPEL de cada slot para uma combinação. `{}` quando a combinação não existe
/// na tabela — e isso é ausência, não default: quem chama decide o que fazer.
export function papeisDe(slug, combinacao) {
  const t = pintura[slug];
  if (!t) return {};
  const chave = t.eixos.map((e) => combinacao[e]);
  const linha = t.linhas.find((l) => l.chave.every((v, i) => v === chave[i]));
  return linha ? linha.pintura : {};
}

/// Papel OU absoluto -> `var(--cps-<nome>)`. Os dois viram variável CSS, e a
/// diferença entre eles é semântica, não hierárquica:
///
/// - **papel** vem de `cps-papeis.css` e MUDA com o modo — quem troca o valor é o
///   seletor, não quem consome;
/// - **absoluto** vem de `cps-tokens.css` e NÃO muda, porque a intenção dele é
///   justamente não reagir ao tema. O divisor sobre cor de marca é branco a 30% no
///   claro e no escuro, e isso é o desenho, não um esquecimento.
///
/// A tabela gerada marca o segundo caso com `{ absoluto: nome }`, e é essa forma que
/// distingue "cor com nome que reage" de "cor com nome que não reage". Cor SEM nome
/// não chega aqui: o gerador recusa a peça antes.
///
/// ## A terceira forma: PAPEL COM ALFA
///
/// `{ papel: 'surfaceSubtle', alfa: 0.702 }` é o vidro do toast, e ele não é uma
/// quarta categoria de cor: é o papel de sempre, modificado. Os dois números vêm
/// declarados do Dart (`s.surfaceSubtle.withValues(alpha: 179/255)`), então o CSS
/// junta os dois sem perder nada.
///
/// > **Alfa não apaga o nome do papel.** Achatar os dois num hex — que é o que a
/// > tabela fazia até 07/09/2026 — perdia a procedência e deixava a peça fora da web.
///
/// `color-mix` contra `transparent` e não `rgba()`: o valor é uma variável, e não dá
/// pra fatiar os canais de uma variável em tempo de CSS. Suportado desde Chrome 111,
/// Safari 16.2 e Firefox 113 — o mesmo piso dos custom elements com Shadow DOM.
export const tinta = (valor) => {
  if (!valor) return null;
  if (typeof valor === 'string') return `var(--cps-${valor})`;
  if (valor.absoluto) return `var(--cps-${valor.absoluto})`;
  if (valor.papel && valor.alfa != null) {
    const pct = +(valor.alfa * 100).toFixed(2);
    return `color-mix(in srgb, var(--cps-${valor.papel}) ${pct}%, transparent)`;
  }
  return valor.papel ? `var(--cps-${valor.papel})` : null;
};

/// As declarações CSS de uma pintura, já traduzidas. Slot ausente não vira
/// `transparent` nem `inherit`: ele simplesmente não é declarado, e o que estiver
/// em volta continua valendo — que é o que o Dart faz quando `border` é nulo.
///
/// Slot DERIVADO (`colorSubtitulo`) também não sai daqui, e por outra razão: ele pinta
/// um pedaço de dentro da peça, não o hospedeiro. Sem o filtro ele saía como
/// `undefined: var(--cps-textTertiary);` — uma declaração inválida, que o navegador
/// descarta calado. Quem precisa dele chama `tinta()` no próprio elemento.
export function estiloDa(papeis) {
  const mapa = { bg: 'background', color: 'color', border: 'border-color' };
  return Object.entries(papeis)
    .filter(([slot]) => mapa[slot])
    .map(([slot, valor]) => `${mapa[slot]}: ${tinta(valor)};`)
    .join(' ');
}

/// O eixo lido do atributo, com o default declarado na SPEC. Atributo ausente e
/// atributo com valor fora do eixo caem no mesmo lugar — o default —, porque a
/// alternativa é o elemento renderizar sem pintura por causa de um typo.
export function eixo(el, nome, valores, padrao) {
  const v = el.getAttribute(nome);
  return valores.includes(v) ? v : padrao;
}
